const Modal = ({ isOpen, onClose, onConfirm, title, description }) => {
    const modalRef = useRef(null);
    const triggerRef = useRef(null);

    useEffect(() => {
        if (isOpen) {
            // Save the current focused element to return focus later
            triggerRef.current = document.activeElement;

            // Focus the first element in the modal
            const focusableElements = modalRef.current.querySelectorAll(
                'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
            );
            if (focusableElements.length > 0) {
                // We want to focus the "Cancel" button by default (safer)
                const cancelButton = Array.from(focusableElements).find(el => el.textContent === 'Cancel');
                if (cancelButton) {
                    cancelButton.focus();
                } else {
                    focusableElements[0].focus();
                }
            }

            // Keyboard listeners
            const handleKeyDown = (e) => {
                if (e.key === 'Escape') onClose();

                // Focus trap
                if (e.key === 'Tab') {
                    const first = focusableElements[0];
                    const last = focusableElements[focusableElements.length - 1];

                    if (e.shiftKey && document.activeElement === first) {
                        last.focus();
                        e.preventDefault();
                    } else if (!e.shiftKey && document.activeElement === last) {
                        first.focus();
                        e.preventDefault();
                    }
                }
            };

            window.addEventListener('keydown', handleKeyDown);
            // Prevent scrolling on body when modal is open
            document.body.style.overflow = 'hidden';

            return () => {
                window.removeEventListener('keydown', handleKeyDown);
                document.body.style.overflow = 'unset';
            };
        } else if (triggerRef.current) {
            // Return focus to the trigger element when modal closes
            triggerRef.current.focus();
        }
